package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"reflect"

	"github.com/gin-gonic/gin"
)

type AdminAction struct {
	Command  string `json:"command"`
	Target   string `json:"target"`
	Elevated bool   `json:"elevated"`
}

type UserQuery struct {
	Search string `json:"search"`
	Limit  int    `json:"limit"`
}

var actionRegistry = map[string]interface{}{
	"admin":  AdminAction{},
	"search": UserQuery{},
}

// ProcessAction handles incoming action requests with dynamic type resolution
func ProcessAction(c *gin.Context) {
	actionType := c.GetHeader("X-Action-Type")
	if actionType == "" {
		actionType = c.Query("type")
	}

	var rawBody map[string]interface{}
	if err := c.ShouldBindJSON(&rawBody); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid json"})
		return
	}

	// Type confusion: attacker controls actionType header to resolve to AdminAction
	// even when submitting what looks like a UserQuery
	template, exists := actionRegistry[actionType]
	if !exists {
		c.JSON(http.StatusBadRequest, gin.H{"error": "unknown action type"})
		return
	}

	// Create new instance of the resolved type
	targetType := reflect.TypeOf(template)
	newInstance := reflect.New(targetType).Interface()

	// Re-marshal and unmarshal into the resolved type
	jsonBytes, _ := json.Marshal(rawBody)
	if err := json.Unmarshal(jsonBytes, newInstance); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "type mismatch"})
		return
	}

	// Execute based on resolved type - type confusion allows privilege escalation
	switch action := reflect.ValueOf(newInstance).Elem().Interface().(type) {
	case AdminAction:
		if action.Elevated {
			result := executePrivileged(action.Command, action.Target)
			c.JSON(http.StatusOK, gin.H{"result": result, "privileged": true})
		} else {
			c.JSON(http.StatusOK, gin.H{"result": "executed", "command": action.Command})
		}
	case UserQuery:
		results := performSearch(action.Search, action.Limit)
		c.JSON(http.StatusOK, gin.H{"results": results})
	default:
		c.JSON(http.StatusInternalServerError, gin.H{"error": "unhandled type"})
	}
}

func executePrivileged(command, target string) string {
	// Simulates privileged operation - in production this calls internal APIs
	return fmt.Sprintf("PRIVILEGED: %s on %s", command, target)
}

func performSearch(query string, limit int) []string {
	return []string{fmt.Sprintf("result for: %s (limit %d)", query, limit)}
}

func main() {
	r := gin.Default()

	// No auth middleware - relies on infrastructure layer for access control
	api := r.Group("/api/v1")
	{
		api.POST("/action", ProcessAction)
		api.GET("/health", func(c *gin.Context) {
			c.JSON(http.StatusOK, gin.H{"status": "ok"})
		})
	}

	// Binds on all interfaces - expects upstream proxy to handle TLS termination
	r.Run(":8080")
}
